<?php
session_start();
require_once __DIR__.'/../../../config/dbconnect.php';
require_once __DIR__.'/../../../config/auth_guard.php';
require_once __DIR__.'/../../../config/securityLogger.php';
require_once __DIR__.'/../../../config/apiSecurity.php';
require_once __DIR__.'/../../../includes/storageService.php';
requireJsonRole([1]);requireActiveAccount($conn,true);enforceRequestSizeLimit(30 * 1024 * 1024);addApiSecurityHeaders();header('Content-Type: application/json');
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['status'=>405,'msg'=>'Method not allowed.']);exit;}
$userId=currentUserId();$useCloudGallery=StorageService::isEnabled();$uploadDir=__DIR__.'/../../../assets/uploads/';
if(!$useCloudGallery&&!is_dir($uploadDir)&&!mkdir($uploadDir,0775,true)){http_response_code(500);echo json_encode(['status'=>500,'msg'=>'Gallery storage is unavailable.']);exit;}
$mimeMap=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'];$maxSize=5*1024*1024;$maxImages=10;
function galleryResponse(int $status,string $msg,array $extra=[]):never{if($status>=400)http_response_code($status);echo json_encode(array_merge(['status'=>$status,'msg'=>$msg],$extra));exit;}
function galleryFiles(string $field,array $mimeMap,int $maxSize):array{$result=[];$files=$_FILES[$field]??null;if(!$files||!is_array($files['name']??null))return $result;$finfo=new finfo(FILEINFO_MIME_TYPE);foreach($files['name'] as $i=>$original){$error=$files['error'][$i]??UPLOAD_ERR_NO_FILE;if($error===UPLOAD_ERR_NO_FILE||$original==='')continue;$tmp=$files['tmp_name'][$i]??'';$size=(int)($files['size'][$i]??0);$mime=$error===UPLOAD_ERR_OK&&is_uploaded_file($tmp)?$finfo->file($tmp):'';if($error!==UPLOAD_ERR_OK||$size<1||$size>$maxSize||!isset($mimeMap[$mime]))galleryResponse(400,'Each image must be a valid JPG, PNG, GIF, or WebP file no larger than 5 MB.');$result[]=['tmp'=>$tmp,'ext'=>$mimeMap[$mime]];}return $result;}
function galleryPost(mysqli $conn,int $postId,int $userId,bool $lock=false):?array{$sql="SELECT id,title,description FROM tbl_gallery_posts WHERE id=? AND uploaded_by=? AND is_archived=0".($lock?' FOR UPDATE':'');$stmt=$conn->prepare($sql);$stmt->bind_param('ii',$postId,$userId);$stmt->execute();$post=$stmt->get_result()->fetch_assoc();$stmt->close();return $post?:null;}

if(isset($_POST['getGalleryPosts'])){
    $stmt=$conn->prepare("SELECT id,title,description,created_at,updated_at FROM tbl_gallery_posts WHERE uploaded_by=? AND is_archived=0 ORDER BY created_at DESC");$stmt->bind_param('i',$userId);$stmt->execute();$res=$stmt->get_result();$posts=[];$imageStmt=$conn->prepare("SELECT id,filename FROM tbl_gallery_images WHERE post_id=? AND is_archived=0 ORDER BY display_order,id");while($post=$res->fetch_assoc()){$postId=(int)$post['id'];$imageStmt->bind_param('i',$postId);$imageStmt->execute();$images=[];$imageRes=$imageStmt->get_result();while($image=$imageRes->fetch_assoc())$images[]=['id'=>(int)$image['id'],'filename'=>StorageService::isCloudinary($image['filename'])?$image['filename']:basename($image['filename'])];$post['id']=$postId;$post['images']=$images;$posts[]=$post;}$imageStmt->close();$stmt->close();galleryResponse(200,'Gallery posts retrieved.',['posts'=>$posts]);
}

requireJsonCsrf();
if(isset($_POST['uploadGallery'])){
    $title=trim($_POST['title']??'');$description=trim($_POST['description']??'');if($title===''||$description==='')galleryResponse(400,'Title and description are required.');if(mb_strlen($title)>255||mb_strlen($description)>2000)galleryResponse(400,'Title or description is too long.');$files=galleryFiles('gallery_images',$mimeMap,$maxSize);if(!$files)galleryResponse(400,'Select at least one valid image.');if(count($files)>$maxImages)galleryResponse(400,"A gallery post can contain up to $maxImages images.");
    // Phase 1: Upload all images to Cloudinary BEFORE opening DB transaction
    $preparedImages=[];
    try{foreach($files as $order=>$file){if($useCloudGallery){$cloudImg=StorageService::upload($file['tmp'],'gallery',['public_id'=>'gallery_'.bin2hex(random_bytes(16))]);$preparedImages[]=['secure_url'=>$cloudImg['secure_url'],'public_id'=>$cloudImg['public_id'],'order'=>$order];}else{$filename='gallery_'.bin2hex(random_bytes(16)).'.'.$file['ext'];$target=$uploadDir.$filename;if(!move_uploaded_file($file['tmp'],$target))throw new RuntimeException('Unable to store an image.');$preparedImages[]=['secure_url'=>$filename,'public_id'=>$target,'order'=>$order];}}}catch(Throwable $e){// Clean up any already-uploaded cloud files
    foreach($preparedImages as $p){if($useCloudGallery)StorageService::delete($p['public_id']);elseif(is_file($p['public_id']))@unlink($p['public_id']);}galleryResponse(500,'Unable to upload one or more images. Please try again.');}
    // Phase 2: Fast DB-only transaction (no network I/O)
    try{$conn->begin_transaction();$stmt=$conn->prepare("INSERT INTO tbl_gallery_posts(title,description,uploaded_by) VALUES (?,?,?)");$stmt->bind_param('ssi',$title,$description,$userId);$stmt->execute();$postId=(int)$conn->insert_id;$stmt->close();$insert=$conn->prepare("INSERT INTO tbl_gallery_images(post_id,filename,display_order) VALUES (?,?,?)");foreach($preparedImages as $p){$filename=$p['secure_url'];$order=$p['order'];$insert->bind_param('isi',$postId,$filename,$order);$insert->execute();}$insert->close();auditLog($conn,'Create Gallery Post',"Created gallery post $title (ID $postId)");SecurityLogger::fileUpload('Gallery Upload', "User $userId uploaded gallery post '$title' (ID $postId) with " . count($preparedImages) . " images");$conn->commit();galleryResponse(201,'Gallery post created successfully.');}catch(Throwable $e){$conn->rollback();foreach($preparedImages as $p){if($useCloudGallery)StorageService::delete($p['public_id']);elseif(is_file($p['public_id']))@unlink($p['public_id']);}galleryResponse(500,'Unable to create the gallery post.');}
}

if(isset($_POST['deleteGalleryPost'])){
    $postId=(int)($_POST['post_id']??0);try{$conn->begin_transaction();$post=galleryPost($conn,$postId,$userId,true);if(!$post){$conn->rollback();galleryResponse(404,'Gallery post not found.');}$imgStmt=$conn->prepare("SELECT filename FROM tbl_gallery_images WHERE post_id=?");$imgStmt->bind_param('i',$postId);$imgStmt->execute();$imgRes=$imgStmt->get_result();$filesToDelete=[];while($img=$imgRes->fetch_assoc()){$filesToDelete[]=$img['filename'];}$imgStmt->close();$delImages=$conn->prepare("DELETE FROM tbl_gallery_images WHERE post_id=?");$delImages->bind_param('i',$postId);$delImages->execute();$delImages->close();$delPost=$conn->prepare("DELETE FROM tbl_gallery_posts WHERE id=? AND uploaded_by=?");$delPost->bind_param('ii',$postId,$userId);$delPost->execute();$delPost->close();auditLog($conn,'Delete Gallery Post',"Deleted gallery post {$post['title']} (ID $postId) with ".count($filesToDelete)." image files");SecurityLogger::fileUpload('Gallery Delete',"User $userId deleted gallery post '{$post['title']}' (ID $postId)");$conn->commit();// Delete files from storage AFTER DB commit (no transaction held open)
    foreach($filesToDelete as $fn){if(StorageService::isCloudinary($fn)){StorageService::delete($fn);}else{$filepath=$uploadDir.basename($fn);if(is_file($filepath))@unlink($filepath);}}galleryResponse(200,'Gallery post deleted successfully.');}catch(Throwable $e){$conn->rollback();galleryResponse(500,'Unable to delete the gallery post.');}
}

if(isset($_POST['updateGallery'])){
    $postId=(int)($_POST['title']??'')===''?(int)($_POST['post_id']??0):(int)($_POST['post_id']??0);$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');if(!$postId||$title===''||$description==='')galleryResponse(400,'Post, title, and description are required.');if(mb_strlen($title)>255||mb_strlen($description)>2000)galleryResponse(400,'Title or description is too long.');$newFiles=galleryFiles('new_images',$mimeMap,$maxSize);$removedIds=array_values(array_unique(array_filter(array_map('intval',explode(',',trim($_POST['removed_images']??''))),fn($id)=>$id>0)));
    // Phase 1: Upload new images to Cloudinary BEFORE opening DB transaction
    $preparedNew=[];
    try{foreach($newFiles as $file){if($useCloudGallery){$cloudImg=StorageService::upload($file['tmp'],'gallery',['public_id'=>'gallery_'.bin2hex(random_bytes(16))]);$preparedNew[]=['secure_url'=>$cloudImg['secure_url'],'public_id'=>$cloudImg['public_id']];}else{$filename='gallery_'.bin2hex(random_bytes(16)).'.'.$file['ext'];$target=$uploadDir.$filename;if(!move_uploaded_file($file['tmp'],$target))throw new RuntimeException('Unable to store an image.');$preparedNew[]=['secure_url'=>$filename,'public_id'=>$target];}}}catch(Throwable $e){foreach($preparedNew as $p){if($useCloudGallery)StorageService::delete($p['public_id']);elseif(is_file($p['public_id']))@unlink($p['public_id']);}galleryResponse(500,'Unable to upload one or more images. Please try again.');}
    // Phase 2: Fast DB-only transaction (no network I/O)
    try{$conn->begin_transaction();$post=galleryPost($conn,$postId,$userId,true);if(!$post){$conn->rollback();foreach($preparedNew as $p){if($useCloudGallery)StorageService::delete($p['public_id']);elseif(is_file($p['public_id']))@unlink($p['public_id']);}galleryResponse(404,'Gallery post not found.');}if($removedIds){$archive=$conn->prepare("UPDATE tbl_gallery_images SET is_archived=1,archived_at=NOW() WHERE id=? AND post_id=? AND is_archived=0");foreach($removedIds as $imageId){$archive->bind_param('ii',$imageId,$postId);$archive->execute();}$archive->close();}$countStmt=$conn->prepare("SELECT COUNT(*),COALESCE(MAX(display_order),-1)+1 FROM tbl_gallery_images WHERE post_id=? AND is_archived=0");$countStmt->bind_param('i',$postId);$countStmt->execute();$countStmt->bind_result($activeCount,$nextOrder);$countStmt->fetch();$countStmt->close();if($activeCount+count($preparedNew)<1)throw new DomainException('A gallery post must keep at least one image.');if($activeCount+count($preparedNew)>$maxImages)throw new DomainException("A gallery post can contain up to $maxImages images.");$insert=$conn->prepare("INSERT INTO tbl_gallery_images(post_id,filename,display_order) VALUES (?,?,?)");foreach($preparedNew as $p){$filename=$p['secure_url'];$insert->bind_param('isi',$postId,$filename,$nextOrder);$insert->execute();$nextOrder++;}$insert->close();$update=$conn->prepare("UPDATE tbl_gallery_posts SET title=?,description=?,updated_at=NOW() WHERE id=? AND uploaded_by=?");$update->bind_param('ssii',$title,$description,$postId,$userId);$update->execute();$update->close();auditLog($conn,'Update Gallery Post',"Updated gallery post $title (ID $postId)");$conn->commit();galleryResponse(200,'Gallery post updated successfully.');}catch(DomainException $e){$conn->rollback();foreach($preparedNew as $p){if($useCloudGallery)StorageService::delete($p['public_id']);elseif(is_file($p['public_id']))@unlink($p['public_id']);}galleryResponse(400,$e->getMessage());}catch(Throwable $e){$conn->rollback();foreach($preparedNew as $p){if($useCloudGallery)StorageService::delete($p['public_id']);elseif(is_file($p['public_id']))@unlink($p['public_id']);}galleryResponse(500,'Unable to update the gallery post.');}
}
galleryResponse(400,'Invalid gallery action.');
